"""`@pytest.mark.refusal` decides what runs on a pull request, so it is linted. No Docker.

Phase 4 puts the marker on the negative cases of the three Stage-1 matrices and takes them off
both PR legs — they carry the highest rot and the least signal per second, and they are the
cheapest thing to run once a night instead of on every push. That makes the marker the one
annotation in this suite whose effect is *less* CI, which is exactly the property that has to be
checked rather than trusted.

Two directions, and they are not symmetric.

* **A marked case that proves no refusal** is the dangerous one: it is a test that quietly
  stopped running on pull requests and still reads as coverage in the file. Checked everywhere,
  no exceptions. A case proves a refusal by calling `assert_refusal(...)` **or** by reading
  `is_error` — several honest negative cases have no authored fragment to name (the server
  answers a bare gramps id, a tuple repr, pydantic prose), `test_00_vocabulary.py` is right to
  reject one, and a lint that demanded the helper would push those cases out of the marker they
  belong in.

* **A refusing case without the marker** merely costs time on the PR tier, and demanding the
  marker everywhere would be wrong: eight committed functions call `assert_refusal` to prove the
  *helper* works, two of them (`test_06_assertions.py`) against a live instance. They are the
  positive control for every marked case that trusts the helper, and moving them into the nightly
  leg would put the control inside the thing it controls. So the marker is enforced **per module,
  once that module uses it** — which is the state that actually goes wrong: half a matrix marked,
  the other half silently back on the PR tier.

There is deliberately **no** "at least one case is marked" assertion here yet. Nothing carries the
marker at this commit, so it would be red on landing; it belongs in the first commit that produces
a refusal case.
"""

from __future__ import annotations

import ast
from pathlib import Path

import pytest
from harness.vocabulary import (
    MARKER,
    Case,
    linted_modules,
    scan_cases,
    scan_cases_tree,
    unmarked,
    unproven,
)

E2E_ROOT = Path(__file__).parent


@pytest.fixture(scope="module")
def cases() -> list[Case]:
    return scan_cases_tree(E2E_ROOT)


# -- the two directions, over the real tree --------------------------------------------


def test_a_marked_case_proves_a_refusal(cases: list[Case]) -> None:
    strays = unproven(cases)

    assert not strays, "marked `refusal` but proves none: " + "; ".join(
        f"{case.origin}:{case.lineno} {case.name}" for case in strays
    )


def test_a_module_that_uses_the_marker_uses_it_everywhere(cases: list[Case]) -> None:
    strays = unmarked(cases)

    assert not strays, "refuses without the marker its module already uses: " + "; ".join(
        f"{case.origin}:{case.lineno} {case.name}" for case in strays
    )


def test_the_scan_sees_the_suite(cases: list[Case]) -> None:
    """Both checks above are green on an empty scan — which is how a guard like this dies:
    somebody renames the helper or the marker and nothing ever reports anything again."""
    assert len(cases) > 300, f"only {len(cases)} functions found under {E2E_ROOT}"
    assert sum(1 for case in cases if case.refuses) >= 8

    refusing_modules = {case.origin for case in cases if case.refuses}
    assert "test_06_assertions.py" in refusing_modules, (
        "the live positive control for assert_refusal is gone — the module the per-module rule "
        "above exists to leave on the PR tier"
    )


def test_both_directions_have_a_population(cases: list[Case]) -> None:
    """Deferred from T4.0 (work-order A8) to the first commit that produces a refusal case.

    Until then the two checks above were vacuously true — nothing carried the marker, so
    "no marked case is unproven" and "no module is half-marked" were statements about the empty
    set, and the lint would have kept passing if the marker had never been applied at all. This
    is the assertion that notices if a whole matrix loses its `refusal` annotations at once, or
    if the marker gets applied and the nightly leg then quietly holds nothing."""
    marked = [case for case in cases if MARKER in case.markers]

    assert marked, "no test carries `refusal`, so the two checks above assert nothing"
    assert {case.origin for case in marked} >= {"test_20_people.py"}, (
        "the people matrix stopped carrying the marker its negative cases were selected for"
    )


def test_the_marker_is_registered(pytestconfig: pytest.Config) -> None:
    """An unregistered marker is a warning, not an error, and `-m 'not refusal'` would then
    deselect nothing while looking like it deselected the nightly half."""
    registered = {line.split(":", 1)[0] for line in pytestconfig.getini("markers")}

    assert MARKER in registered


# -- the guard's own falsification ------------------------------------------------------


def parse(sample: str) -> list[Case]:
    return scan_cases(ast.parse(sample), "sample.py")


MARKED_WITHOUT_PROOF = """
import pytest

@pytest.mark.refusal
def test_it():
    result = mcp.call("gramps_delete_person", {})
    assert result.text
"""

MARKED_WITH_THE_HELPER = """
import pytest

@pytest.mark.refusal
def test_it():
    assert_refusal(rest, mcp, "t", {}, contains="requires confirm=True")
"""

MARKED_WITH_THE_FLAG = """
import pytest

@pytest.mark.refusal
def test_it():
    result = mcp.call("gramps_delete_family", {})
    assert result.is_error
"""


def test_a_marked_case_with_no_proof_is_reported() -> None:
    assert [case.name for case in unproven(parse(MARKED_WITHOUT_PROOF))] == ["test_it"]


def test_the_helper_counts_as_proof() -> None:
    assert unproven(parse(MARKED_WITH_THE_HELPER)) == []


def test_the_wire_flag_counts_as_proof() -> None:
    """The case that has no authored fragment to name — the reason direction A takes either."""
    assert unproven(parse(MARKED_WITH_THE_FLAG)) == []


